import {researchSource,safeUrl} from './sources.js';
export function kindLabel(kind){return ({'visitor-review':'历史到访评论','public-discussion':'公开讨论',imported:'导入 / 未核实',manual:'手动 / 未核实'})[kind]||'来源待核实';}
export function reviewLabel(status){return ({pending:'待复核',accepted:'值得参考',rejected:'暂不采用'})[status]||'待复核';}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function sourceLink(url,label){const href=safeUrl(url?.startsWith('./')?new URL(url,location.href).href:url);return href?`<a href="${esc(href)}" target="_blank" rel="noopener noreferrer" data-source-link>${esc(label)} ↗</a>`:'来源链接未提供';}
export function provenanceBanner(){return `<div class="notice evidence-notice"><b>真实评论，示例馆资源，规则分析。</b> 内置数据来自公开研究附件，非实时抓取。到访后评价与潜在需求分别处理；来源馆的历史评论不代表当前工作空间博物馆的评价。旧版编造评论已退出当前数据集。${sourceLink(researchSource.url,'来源与 CC BY 4.0 许可')}</div>`;}
export function provenanceCard(p){return `<section class="provenance-card"><div class="panel-title"><h4>原文来源与边界</h4><span class="tag teal">${kindLabel(p.kind)}</span></div><dl><dt>来源</dt><dd>${esc(p.source)}${p.declaredSource?'（用户声明：'+esc(p.declaredSource)+'）':''}</dd><dt>评论对象</dt><dd>${esc(p.museumName||p.threadTitle||'未指定，不推断')}</dd><dt>原评日期</dt><dd>${esc(p.date||'未知')} · 采集 / 载入 ${esc(p.collectedAt?.slice(0,10)||'未知')}</dd><dt>证据定位</dt><dd>${sourceLink(p.evidenceUrl||p.sourceUrl,p.sourcePage?'研究附件第 '+p.sourcePage+(p.sourceEndPage!==p.sourcePage?'—'+p.sourceEndPage:'')+' 页，记录 '+p.sourceRow:'原评论')}</dd><dt>原平台</dt><dd>${sourceLink(p.sourceUrl,p.kind==='visitor-review'?'景点页面（不是逐条评论永久链接）':'原评论链接')}</dd><dt>处理</dt><dd>${esc(p.provenance||'未提供处理记录')}</dd><dt>许可 / 署名</dt><dd>${esc(p.license||'用户自行确认使用权限')} ${esc(p.attribution||'')}</dd></dl>${p.datasetUrl?`<small>${sourceLink(p.datasetUrl,'研究数据集')} · ${sourceLink('./provenance.json','查看数据处理清单')}</small>`:''}</section>`;}
export function reviewControls(p){return `<div class="review-controls"><span>人工复核：<b>${reviewLabel(p.review)}</b></span>${[['accepted','值得参考'],['rejected','暂不采用'],['pending','重置复核']].map(([v,l])=>`<button data-review-id="${esc(p.id)}" data-review-value="${v}">${l}</button>`).join('')}<small>暂不采用的内容保留在数据表，但不进入机会聚合；人工复核不改变规则分数。</small></div>`;}
export function highlight(text,hits){const terms=[...new Set(hits)].sort((a,b)=>b.length-a.length);if(!terms.length)return esc(text);const pattern=new RegExp(terms.map(x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'gi');let html='',pos=0;for(const m of text.matchAll(pattern)){html+=esc(text.slice(pos,m.index))+'<mark>'+esc(m[0])+'</mark>';pos=m.index+m[0].length;}return html+esc(text.slice(pos));}
